const body = $json.body || $json;

const company_name = body.company_name || 'Carrier Client';
const owner_name = body.owner_name || 'Driver / Owner';
const phone = body.phone || 'N/A';
const email = body.email || '';
const mc_dot = body.mc_dot || 'Pending';
const equipment = body.equipment || 'Dry Van';
const factoring_status = body.factoring_status || 'not_factoring';
const monthly_gross = body.monthly_gross || '10k_25k';
const authority_age = body.authority_age || 'over_90_days';

// Prequalification Engine Logic:
// 1. BasicBlock for:
//    - New authority (< 90 days)
//    - Low monthly volume (< $10,000/mo)
//    - Contract-phobic / locked into strict contract / selective spot factoring only
// 2. Summar Financial for:
//    - Established authority (> 90 days)
//    - Mid-to-high volume ($10,000 - $25,000 or $25,000 - $50,000+/mo)
//    - Running Semi (Dry Van / Reefer / Flatbed) or Box Truck

let qualifiedTier = 'SUMMAR';
let reason = 'Qualified for Summar Financial premium non-recourse credit protection and same-day funding.';

if (authority_age === 'under_90_days' || monthly_gross === 'under_10k' || factoring_status === 'locked_contract') {
    qualifiedTier = 'BASICBLOCK';
    reason = 'Best match for BasicBlock 2.5% flat non-recourse rate with zero contracts and $5 same-day RTP.';
}

return {
    json: {
        company_name,
        owner_name,
        phone,
        email,
        mc_dot,
        equipment,
        factoring_status,
        monthly_gross,
        authority_age,
        qualifiedTier,
        reason,
        timestamp: new Date().toISOString()
    }
};

